import { z } from 'zod';
import { metaBase, inputImage } from './meta-contracts';
import { brandInputSchema } from '../db/schema';

/** Remix input: a finished ad plus the new angle. The model repaints the
 *  ad; the headline is generated by the model, as the owner chose. */
export const remixRequestSchema = metaBase.extend({
  imageConsent: z.literal(true),
  image: inputImage,
  brand: brandInputSchema,
  scene: z.string().trim().min(1).max(1000),
  headline: z.string().trim().min(1).max(200),
  language: z.enum(['en', 'ar']),
}).strict();

export function buildRemixPrompt(brand: { name: string; colors: [string, string, string] }, scene: string, headline: string, language: 'en' | 'ar'): string {
  const lines = [
    'This is a finished advertisement. Create a new version of the same ad.',
    'Keep the exact same product — same shape, colors, packaging and identity — and the same brand logo, in the same top-right zone.',
    `Change the background scene to: ${scene}.`,
    `Change the headline to "${headline}", rendered exactly as written, placed in the top zone. Remove the old headline and any other old text; the new headline is the only headline.`,
    `Brand: ${brand.name}. Brand colors: ${brand.colors.join(', ')}. Echo them in the scene.`,
  ];
  if (language === 'ar') lines.push('Any text in the image is Arabic unless it is the Latin brand name.');
  lines.push('No extra text, no extra logos, no watermark, no objects cropped by the frame edges.');
  return lines.join(' ');
}

/** Seasonal themes for the themes page. Scene text is model-prompt
 *  English; display names live in the messages files. */
export const REMIX_THEMES = [
  { id: 'ramadan', scene: 'Ramadan atmosphere: warm golden lantern light, crescent motifs, dates and Arabic coffee details, festive yet elegant evening mood' },
  { id: 'eid', scene: 'Eid celebration: joyful festive decorations, balloons and gifts, bright celebratory colors, happy holiday mood' },
  { id: 'black-friday', scene: 'Black Friday sale atmosphere: bold dark background with striking sale energy, dramatic lighting, high-contrast promotional mood' },
  { id: 'summer', scene: 'Summer freshness: bright sunlight, cool water and beach tones, light airy vacation mood' },
] as const;
export type RemixThemeId = (typeof REMIX_THEMES)[number]['id'];
